begin; select set_config('request.jwt.claims','{"role":"service_role"}',true); do $test$ declare s public.clinicorp_payment_snapshot%rowtype; j bigint; token uuid:=gen_random_uuid(); r jsonb; actual numeric; begin if private.clinicorp_newest_payload('{"Version":5,"Amount":250}'::jsonb,'{"Version":4,"Amount":100}'::jsonb)->>'Amount'<>'250' then raise exception 'Older version won'; end if; select x.* into s from public.clinicorp_payment_snapshot x join public.patient_units pu on pu.unit_id=x.unit_id and pu.clinicorp_patient_id=x.clinicorp_patient_id and pu.is_active where lower(x.payment_form) like '%boleto%' and x.amount>0 and x.due_date is not null and not x.payment_received and not x.payment_confirmed and not x.cancelled and x.posting_day is not null and not exists(select 1 from public.installments i where i.unit_id=x.unit_id and i.clinicorp_installment_id=x.clinicorp_payment_id) order by x.unit_id,x.clinicorp_payment_id limit 1; if s.clinicorp_payment_id is null then raise exception 'No repair fixture'; end if; insert into private.clinicorp_sync_days(unit_id,posting_day,status,phase,payload,returned_rows,apply_cursor,observed_at,lease_token,lease_until) values(s.unit_id,s.posting_day,'working','apply',jsonb_build_array(s.raw||jsonb_build_object('id',s.clinicorp_payment_id)),1,0,clock_timestamp(),token,clock_timestamp()+interval '2 minutes') on conflict(unit_id,posting_day) do update set status='working',phase='apply',payload=excluded.payload,returned_rows=1,apply_cursor=0,observed_at=excluded.observed_at,lease_token=token,lease_until=excluded.lease_until returning id into j; r:=public.apply_clinicorp_sync_batch(j,token,25); if r->>'phase'<>'verify' or (r->>'rows')::integer<>1 then raise exception 'Cursor did not advance: %',r; end if; select expected_amount-paid_amount into actual from public.installments where unit_id=s.unit_id and clinicorp_installment_id=s.clinicorp_payment_id; if actual is distinct from s.amount then raise exception 'Source balance differs: % vs %',actual,s.amount; end if; update private.clinicorp_sync_days set phase='apply',apply_cursor=0 where id=j; r:=public.apply_clinicorp_sync_batch(j,token,25); if (r->>'changed')::integer<>0 then raise exception 'Replay rewrote financial rows: %',r; end if; begin perform public.apply_clinicorp_sync_batch(j,gen_random_uuid(),25); raise exception 'Expired lease accepted'; exception when sqlstate '55000' then null; end; perform public.finish_clinicorp_sync_job(j,token); end $test$; rollback;
